#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;

struct Node {
    int key, pri, l, r;
} t[100001];
int tot, root;

int newNode(int key) {
    tot++;
    t[tot].key = key;
    t[tot].pri = rand();
    t[tot].l = t[tot].r = 0;
    return tot;
}

void split(int u, int key, int &x, int &y) {
    if (!u) { x = y = 0; return; }
    if (t[u].key <= key) {
        x = u;
        split(t[u].r, key, t[u].r, y);
    } else {
        y = u;
        split(t[u].l, key, x, t[u].l);
    }
}

int merge(int x, int y) {
    if (!x || !y) return x | y;
    if (t[x].pri > t[y].pri) {
        t[x].r = merge(t[x].r, y);
        return x;
    } else {
        t[y].l = merge(x, t[y].l);
        return y;
    }
}

void insert(int &root, int key) {
    int x, y;
    split(root, key, x, y);
    root = merge(merge(x, newNode(key)), y);
}

bool search(int u, int key) {
    if (!u) return false;
    if (t[u].key == key) return true;
    if (key < t[u].key) return search(t[u].l, key);
    return search(t[u].r, key);
}

int main() {
    srand(time(0));
    insert(root, 5);
    insert(root, 3);
    insert(root, 7);
    insert(root, 1);
    insert(root, 4);
    cout << "查找3: " << (search(root, 3) ? "存在" : "不存在") << endl;
    cout << "查找6: " << (search(root, 6) ? "存在" : "不存在") << endl;
    return 0;
}

#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;

struct Node {
    int key, pri, l, r, size;
} t[100001];
int tot, root;

int newNode(int key) {
    tot++;
    t[tot].key = key;
    t[tot].pri = rand();
    t[tot].l = t[tot].r = 0;
    t[tot].size = 1;
    return tot;
}

void pushUp(int u) {
    t[u].size = 1 + t[t[u].l].size + t[t[u].r].size;
}

void splitByKey(int u, int key, int &x, int &y) {
    if (!u) { x = y = 0; return; }
    if (t[u].key <= key) {
        x = u;
        splitByKey(t[u].r, key, t[u].r, y);
    } else {
        y = u;
        splitByKey(t[u].l, key, x, t[u].l);
    }
    pushUp(u);
}

int merge(int x, int y) {
    if (!x || !y) return x | y;
    if (t[x].pri > t[y].pri) {
        t[x].r = merge(t[x].r, y);
        pushUp(x);
        return x;
    } else {
        t[y].l = merge(x, t[y].l);
        pushUp(y);
        return y;
    }
}

void insert(int &root, int key) {
    int x, y;
    splitByKey(root, key, x, y);
    root = merge(merge(x, newNode(key)), y);
}

void erase(int &root, int key) {
    int x, y, z;
    splitByKey(root, key, x, z);
    splitByKey(x, key - 1, x, y);
    y = merge(t[y].l, t[y].r);
    root = merge(merge(x, y), z);
}

int getRank(int root, int key) {
    int x, y;
    splitByKey(root, key - 1, x, y);
    int res = t[x].size + 1;
    root = merge(x, y);
    return res;
}

int main() {
    srand(time(0));
    insert(root, 5);
    insert(root, 3);
    insert(root, 7);
    insert(root, 1);
    insert(root, 4);
    insert(root, 6);
    insert(root, 8);
    cout << "5的排名: " << getRank(root, 5) << endl;
    erase(root, 5);
    cout << "删除5后，5的排名: " << getRank(root, 5) << endl;
    return 0;
}
